            stopEventStream() {streamAbort?.abort();streamAbort=null;this.streamRun=null;this.streamConnected=false;},
            ensureEventStream(runId) {if(this.streamRun===runId)return;this.stopEventStream();this.streamRun=runId;this.streamSeq=0;this.streamGone=false;this.liveSegments=[];this.liveTools=[];this.watchEventStream(runId,this.epoch);},
